"""Report part: continuous county broadband coverage (NTIA NBM 2010-14, FCC 477 2014-21) and the AT&T December-2010 mobile footprint
against the state youth-survey county panel and NVSS youth suicide (results/tables/bb_*.csv from scripts/analysis/34_broadband_instruments.py)."""
def build(ctx):
    pd, np, go = ctx.pd, ctx.np, ctx.go; T = ctx.T; f = ctx.fmt
    dose = pd.read_csv(T/"bb_dose_results.csv"); ev = pd.read_csv(T/"bb_att_event_mn.csv"); dd = pd.read_csv(T/"bb_att_did_mn.csv"); ld = pd.read_csv(T/"bb_att_longdiff_mn.csv")
    tr = pd.read_csv(T/"bb_att_trend_states.csv"); asum = pd.read_csv(T/"bb_att_summary.csv").set_index("stat").value; ps = pd.read_csv(T/"bb_panel_summary.csv").set_index("round")
    sr = pd.read_csv(T/"bb_suicide_results.csv"); ss = pd.read_csv(T/"bb_suicide_samples.csv").set_index("sample"); sc_mn = pd.read_csv(T/"bb_scatter_mn_considered.csv")
    lte = pd.read_csv(T/"state_survey_lte_did.csv").set_index("series"); ntia = pd.read_csv(T/"state_survey_ntia_dose.csv")
    has_state = (T/"bb_suicide_state_results.csv").exists()
    if has_state: st = pd.read_csv(T/"bb_suicide_state_results.csv"); stev = pd.read_csv(T/"bb_suicide_state_event.csv"); sc_st = pd.read_csv(T/"bb_scatter_suicide_state.csv")
    g = lambda df, **k: df[np.logical_and.reduce([df[c] == v for c, v in k.items()])].iloc[0]
    MEAS = {"wireline_any": "Any wireline (DSL, cable, fiber)", "wireline_ge10": "Wireline, 10 Mbps or faster", "wireline_ge25": "Wireline, 25 Mbps or faster", "fixed_ge25": "Fixed terrestrial, 25/3 Mbps", "mobile_any": "Mobile wireless (3G/4G), 2010-14 only", "anytech_ge10": "Any technology, 10 Mbps, 2011-14 only"}
    SEXL = {"all": "all", "female": "girls", "male": "boys"}
    # ---- chart 1: dose coefficients and the Minnesota AT&T event study
    fig = ctx.make_subplots(rows=1, cols=2, column_widths=[0.5, 0.5], subplot_titles=("County coverage dose, 2010-21", "Minnesota: AT&T 2010 share x wave (ref. 2007)"), horizontal_spacing=0.12)
    d21 = dose[(dose["sample"] == "2010-2021") & (dose.sex == "all")]; order = [m for m in MEAS if m in set(d21.measure)]
    for item, col, off, lab in [("sad_hopeless", ctx.PAL[3], -0.15, "Sad or hopeless (CA IL ME PA WA)"), ("considered_suicide", ctx.PAL[6], 0.15, "Considered suicide (6 states)")]:
        s = d21[d21.item == item].set_index("measure").reindex(order).dropna(subset=["coef_per10pp"]); ypos = [order.index(m) + off for m in s.index]
        fig.add_trace(go.Scatter(x=s.coef_per10pp, y=ypos, mode="markers", name=lab, marker=dict(color=col, size=9), error_x=dict(type="data", array=1.96 * s.se_per10pp, color=col, thickness=1.2), hovertemplate="%{text}: %{x:+.2f} pp<extra></extra>", text=[MEAS[m] for m in s.index]), row=1, col=1)
    fig.add_vline(x=0, line=dict(color=ctx.MUTED, width=1), row=1, col=1)
    fig.update_yaxes(tickvals=list(range(len(order))), ticktext=[MEAS[m] for m in order], autorange="reversed", row=1, col=1); fig.update_xaxes(title_text="percentage points per +10 pp covered (95% CI)", row=1, col=1)
    for item, col, lab in [("considered_suicide", ctx.PAL[6], "Considered suicide, grade 9"), ("attempted_suicide", ctx.PAL[7], "Attempted suicide, grade 9"), ("sad_hopeless", ctx.PAL[3], "Sad most of last 30 days (to 2010)")]:
        e = ev[ev.item == item].sort_values("year")
        fig.add_trace(go.Scatter(x=e.year, y=e.coef, mode="lines+markers", name=lab, line=dict(color=col, width=2), marker=dict(size=7), error_y=dict(type="data", array=1.96 * e.se, color=col, thickness=1), hovertemplate="%{x}: %{y:+.2f} pp<extra></extra>"), row=1, col=2)
    fig.add_vrect(x0=2007.4, x1=2011.1, fillcolor="rgba(128,128,128,.12)", line_width=0, row=1, col=2, annotation_text="AT&T iPhone exclusivity", annotation_position="top left", annotation_font_size=10)
    fig.add_hline(y=0, line=dict(color=ctx.MUTED, width=1), row=1, col=2); fig.update_xaxes(title_text="Minnesota Student Survey wave", row=1, col=2); fig.update_yaxes(title_text="pp, 100% vs 0% AT&T coverage", row=1, col=2)
    ctx.figs["bb_coefficients"] = ctx.base(fig, h=440, hovermode="closest", legend=dict(orientation="h", y=-0.22, x=0))
    # ---- chart 2: scatters
    fig2 = ctx.make_subplots(rows=1, cols=2, subplot_titles=("Minnesota counties: ideation change 2007-2019", "States: youth suicide change, 2003-07 to 2013-17" if has_state else "Counties: youth suicide change"), horizontal_spacing=0.1)
    fig2.add_trace(go.Scatter(x=100 * sc_mn.att, y=sc_mn.change_2007_2019, mode="markers", name="MN county (size = 2000 population)", marker=dict(color=[ctx.PAL[0] if m else ctx.PAL[1] for m in sc_mn.metro], size=np.clip(4 + np.sqrt(sc_mn.population_2000) / 40, 5, 28), opacity=0.7, line=dict(width=0.5, color="white")),
                              text=sc_mn.fips.astype(str), hovertemplate="county %{text}: AT&T %{x:.0f}%, change %{y:+.1f} pp<extra></extra>"), row=1, col=1)
    x = sc_mn.att * 100; b = np.polyfit(x, sc_mn.change_2007_2019, 1, w=np.sqrt(sc_mn.population_2000)); xs = np.array([0, 100])
    fig2.add_trace(go.Scatter(x=xs, y=np.polyval(b, xs), mode="lines", name="pop-weighted fit", line=dict(color=ctx.MUTED, dash="dot"), hoverinfo="skip"), row=1, col=1)
    fig2.update_xaxes(title_text="share of county population with AT&T mobile coverage, Dec 2010 (%)", row=1, col=1); fig2.update_yaxes(title_text="pp change, considered suicide (grade 9)", row=1, col=1)
    if has_state:
        fig2.add_trace(go.Scatter(x=100 * sc_st.att_state, y=sc_st.change, mode="markers", name="state (size = youth population)", marker=dict(color=ctx.PAL[2], size=np.clip(4 + np.sqrt(sc_st["pop"]) / 60, 5, 30), opacity=0.75, line=dict(width=0.5, color="white")), text=sc_st.state_fips.astype(str), hovertemplate="state %{text}: AT&T %{x:.0f}%, %{y:+.2f} per 100k<extra></extra>"), row=1, col=2)
        b2 = np.polyfit(100 * sc_st.att_state, sc_st.change, 1, w=np.sqrt(sc_st["pop"])); fig2.add_trace(go.Scatter(x=xs, y=np.polyval(b2, xs), mode="lines", name="pop-weighted fit", line=dict(color=ctx.MUTED, dash="dot"), showlegend=False, hoverinfo="skip"), row=1, col=2)
        fig2.update_xaxes(title_text="state population-weighted AT&T coverage, Dec 2010 (%)", row=1, col=2); fig2.update_yaxes(title_text="change in deaths per 100,000 per year", row=1, col=2)
    ctx.figs["bb_scatter"] = ctx.base(fig2, h=420, hovermode="closest", legend=dict(orientation="h", y=-0.22, x=0))
    # ---- numbers for the prose
    r25 = g(dose, measure="wireline_ge25", item="considered_suicide", sex="all", sample="2010-2021"); r10 = g(dose, measure="wireline_ge10", item="considered_suicide", sex="all", sample="2010-2021"); rany = g(dose, measure="wireline_any", item="considered_suicide", sex="all", sample="2010-2021")
    s25 = g(dose, measure="wireline_ge25", item="sad_hopeless", sex="all", sample="2010-2021"); r25_19 = g(dose, measure="wireline_ge25", item="considered_suicide", sex="all", sample="2010-2019"); r10_19 = g(dose, measure="wireline_ge10", item="considered_suicide", sex="all", sample="2010-2019")
    r25f = g(dose, measure="wireline_ge25", item="considered_suicide", sex="female", sample="2010-2021"); r25m = g(dose, measure="wireline_ge25", item="considered_suicide", sex="male", sample="2010-2021"); s25f = g(dose, measure="wireline_ge25", item="sad_hopeless", sex="female", sample="2010-2021")
    mob = g(dose, measure="mobile_any", item="considered_suicide", sex="all", sample="2010-2021"); mobs = g(dose, measure="mobile_any", item="sad_hopeless", sex="all", sample="2010-2021")
    lte_sad = lte.loc[[i for i in lte.index if i.startswith("Sad/hopeless")][0]]; lte_con = lte.loc[[i for i in lte.index if i.startswith("Considered suicide, WA+ME+MN")][0]]
    cs = dd[dd.item == "considered_suicide"].set_index("spec"); at = dd[dd.item == "attempted_suicide"].set_index("spec"); sd30 = dd[dd.item == "sad_hopeless"].set_index("spec")
    P, B, PRE, VZ = "att share (0-1) x post-2007", "Myers-Hooper binary: treated (>90%) vs control (<10%) x post-2007", "pre-trend 1998-2007: att x waves (per 3-year wave)", "comparison: Verizon share (0-1) x post-2007 (no iPhone until Feb 2011)"
    e19 = g(ev, item="considered_suicide", year=2019); e13 = g(ev, item="considered_suicide", year=2013); e10 = g(ev, item="considered_suicide", year=2010); e98 = g(ev, item="considered_suicide", year=1998); e04 = g(ev, item="considered_suicide", year=2004)
    ld19 = g(ld, item="considered_suicide", window="2007->2019", controls="none", weights="pop-2000 weighted"); ld19c = g(ld, item="considered_suicide", window="2007->2019", controls="metro + log pop", weights="pop-2000 weighted"); ldp = g(ld, item="considered_suicide", window="placebo 2001->2007", controls="none", weights="pop-2000 weighted")
    pool = g(tr, item="considered_suicide", sex="all", spec="pooled: att x (years since 2010)/10, county x grade + state x year FE"); pools = g(tr, item="sad_hopeless", sex="all", spec="pooled: att x (years since 2010)/10, county x grade + state x year FE")
    poolf = g(tr, item="considered_suicide", sex="female", spec="pooled: att x (years since 2010)/10, county x grade + state x year FE"); poolm = g(tr, item="considered_suicide", sex="male", spec="pooled: att x (years since 2010)/10, county x grade + state x year FE")
    uns = g(sr, sex="all", window="2003-2007 -> 2013-2017", regressor="AT&T Dec-2010 share (0-1)", sample="unsuppressed counties", controls="none"); unsc = g(sr, sex="all", window="2003-2007 -> 2013-2017", regressor="AT&T Dec-2010 share (0-1)", sample="unsuppressed counties", controls="metro + log youth pop")
    imp = g(sr, sex="all", window="2003-2007 -> 2013-2017", regressor="AT&T Dec-2010 share (0-1)", sample="all counties (suppressed set to 5)", controls="none"); impc = g(sr, sex="all", window="2003-2007 -> 2013-2017", regressor="AT&T Dec-2010 share (0-1)", sample="all counties (suppressed set to 5)", controls="metro + log youth pop")
    big = ss.loc["large counties (>=50,000 youths/yr)"]
    att_mean, n_tr, n_co, n_int = float(asum["mean att share (unweighted)"]), int(float(asum["counties treated (>90% in block groups, Myers-Hooper)"])), int(float(asum["counties control (<10%)"])), int(float(asum["counties intermediate"]))
    att_metro, att_non, att_lte, att_late, r_vz, r_lte = (float(asum[k]) for k in ["mean att share, metro counties", "mean att share, non-metro counties", "mean att share, counties with LTE by school year 2012", "mean att share, dated-LTE counties with LTE after 2012 or undated", "correlation att share vs Verizon share", "correlation att share vs LTE onset year (dated metros)"])
    pct = lambda x: f"{100*x:.0f}%"
    # ---- tables
    rows = []
    for m in order:
        r = [MEAS[m]]
        for item in ["sad_hopeless", "considered_suicide"]:
            for sx in ["all", "female", "male"]:
                q = dose[(dose.measure == m) & (dose.item == item) & (dose.sex == sx) & (dose["sample"] == "2010-2021")]
                r.append(f(q.coef_per10pp.iloc[0], q.se_per10pp.iloc[0], bold_t=1.96) + f"<br><small>n={int(q.n.iloc[0])}, {int(q.counties.iloc[0])} counties</small>" if len(q) else "<span class=muted>-</span>")
        q19 = dose[(dose.measure == m) & (dose.item == "considered_suicide") & (dose.sex == "all") & (dose["sample"] == "2010-2019")]
        r.append(f(q19.coef_per10pp.iloc[0], q19.se_per10pp.iloc[0], bold_t=1.96) if len(q19) else "-"); rows.append(r)
    t_dose = ctx.table(["County coverage measure", "Sad/hopeless, all", "girls (CA, ME)", "boys (CA, ME)", "Considered suicide, all", "girls (CA, ME)", "boys (CA, ME)", "Considered suicide, all, 2010-19 only"], rows)
    rows = []
    for item, lab in [("considered_suicide", "Considered suicide (grade 9, 1998-2019)"), ("attempted_suicide", "Attempted suicide (grade 9, 1998-2019)"), ("sad_hopeless", "Sad all/most of the last 30 days (1998-2010)"), ("hopeless_30d", "Discouraged or hopeless, 30 days (1998-2010)"), ("nervous_30d", "Nervous or worried, 30 days (1998-2010)"), ("stress_high", "Under great stress, 30 days (1998-2010)")]:
        q = dd[dd.item == item].set_index("spec"); rows.append([lab, f"{q.loc[P, 'mean_pre2007']:.1f}", f(q.loc[PRE, "coef"], q.loc[PRE, "se"]), f(q.loc[P, "coef"], q.loc[P, "se"], bold_t=1.96), f(q.loc[B, "coef"], q.loc[B, "se"], bold_t=1.96), f(q.loc[VZ, "coef"], q.loc[VZ, "se"]), f"{int(q.loc[P, 'n'])} / {int(q.loc[P, 'counties'])}"])
    t_mn = ctx.table(["Minnesota item", "Mean to 2007 (%)", "Pre-trend 1998-2007 (pp per wave)", "AT&T share x post-2007 (pp)", "Treated vs control x post (pp)", "Verizon share x post (pp)", "n / counties"], rows)
    rows = [["Counties with unsuppressed counts in both periods (zeros reported, 1-9 suppressed)", f"{int(uns.n)} ({pct(uns.share_us_pop)} of youth)", f(uns.coef, uns.se, bold_t=1.96), f(unsc.coef, unsc.se, bold_t=1.96)],
            ["All counties, suppressed counts set to the midpoint 5", f"{int(imp.n)} ({pct(imp.share_us_pop)})", f(imp.coef, imp.se, bold_t=1.96), f(impc.coef, impc.se, bold_t=1.96)]]
    for sx, lab in [("F", "girls"), ("M", "boys")]:
        for samp, sl in [("unsuppressed counties", "unsuppressed counties"), ("all counties (suppressed set to 5)", "all counties, midpoint-imputed")]:
            q = sr[(sr.sex == sx) & (sr.window == "2003-2007 -> 2013-2017") & (sr.regressor == "AT&T Dec-2010 share (0-1)") & (sr["sample"] == samp)]
            if len(q): rows.append([f"{lab}, {sl}", f"{int(q.n.iloc[0])} ({pct(q.share_us_pop.iloc[0])})", f(q[q.controls == 'none'].coef.iloc[0], q[q.controls == 'none'].se.iloc[0], bold_t=1.96), f(q[q.controls != 'none'].coef.iloc[0], q[q.controls != 'none'].se.iloc[0], bold_t=1.96)])
    if has_state:
        for sx, lab in [("all", "States, all youth"), ("F", "States, girls"), ("M", "States, boys")]:
            q = st[(st.sex == sx)].set_index("spec")
            if len(q):
                nmc = q.loc["same, controlling the state's non-metro population share x post-2007"] if "same, controlling the state's non-metro population share x post-2007" in q.index else None
                rows.append([f"<strong>{lab}</strong>: state AT&T share x post-2007, 1999-2024 state x year panel, state + year FE", f"{int(q.iloc[0].n)} state-years, {int(q.iloc[0].states)} states", f(q.iloc[0].coef, q.iloc[0].se, bold_t=1.96), (f(nmc.coef, nmc.se, bold_t=1.96) + " <small>(non-metro share x post)</small>") if nmc is not None else "-"])
    t_su = ctx.table(["Youth (10-19) suicide, change in deaths per 100,000 per year, 2003-07 to 2013-17, on AT&T share (0-1)", "n (share of U.S. youth)", "No controls", "Metro + log youth population"], rows)
    lit = ctx.table(["Study", "Identifying variation", "Outcome and finding"], [
        ["<a href='https://www.nber.org/papers/w35310'>Myers &amp; Hooper 2026</a> (NBER 35310)", "County AT&T mobile-broadband coverage in the NTIA SBI December-2010 release x the June 2007 - February 2011 iPhone exclusivity; counties with more than 90% vs less than 10% of population covered", "County birth rates (NCHS): births to 15-19-year-olds fell 2.0-9.0% (abstract, October 2026 revision), 20-24 1.5-7.2%; smartphone diffusion explains 12-53% of the 2007-11 fertility decline"],
        ["<a href='https://www.nber.org/papers/w34614'>Churchill &amp; Johnson 2026</a> (NBER 34614)", "State broadband access built from FCC deployment data, 2009-2019 (county coverage rose from under 70% to about 90%)", "National and state YRBS: a one-SD rise in access raises suicidal ideation 9.3-16.5%, largest for girls; more cyberbullying and body dissatisfaction (girls), less sleep (boys)"],
        ["<a href='https://www.nber.org/papers/w32517'>Johnson &amp; Persico 2024</a> (NBER 32517)", "County broadband access growth 2000-2008", "All-age suicides: a 10% rise in the share with access lowers county suicides 1.01%, via poverty and unemployment; effects among adults 25-64"],
        ["<a href='https://doi.org/10.58567/jie04010001'>Wang 2026</a> (J. Information Economics 4(1))", "State broadband connections per capita 2006-2023 instrumented with county distance to rivers/coasts and 1870 railroad length", "Suicide deaths ages 15-24: one SD more connections (0.06 per capita) lowers the crude rate by 4.97 per 100,000 (2SLS)"],
        ["<a href='https://doi.org/10.2139/ssrn.3949645'>Donati et al. 2025</a> (JHE)", "Italian municipalities' access to high-speed internet", "Youth mental-health diagnoses rise (as cited in Part 2)"],
        ["<a href='https://doi.org/10.1016/j.jhealeco.2025.103014'>Arenas-Arroyo et al. 2025</a> (JHE)", "Spanish fibre-to-the-home rollout 2007-2019", "Adolescent hospital mental-health and self-harm diagnoses rise, concentrated among girls"],
        ["<a href='https://doi.org/10.1002/hec.4570'>Golin 2022</a> (Health Economics)", "German DSL availability shaped by legacy telephone infrastructure", "Worse mental health for women; widening gender gap"],
        ["<a href='https://doi.org/10.1016/j.jhealeco.2019.102274'>McDool et al. 2020</a> (JHE)", "UK neighbourhood broadband speed", "Lower well-being among children, especially girls"],
        ["<a href='http://hdl.handle.net/1807/130332'>Guo 2023</a>", "British Columbia mountain towns gaining high-speed fixed wireless after 2014", "Girls' severe school mental-health designations rise about 1 pp"]])
    # ---- prose
    html = f"""<h3 id="broadband">Continuous broadband coverage and the AT&amp;T 2010 footprint at county level</h3>
<p>Part 2 interpreted the null for 4G LTE launch dates as a timing problem: the 2011-13 metro upgrades came after smartphones and mobile social media had already spread, and were compressed into two years. This section replaces the launch dates with two public county series that carry more variation. The first is continuous coverage: the share of each county's population with wireline, fixed and mobile broadband available, by advertised speed tier, from the NTIA State Broadband Initiative's National Broadband Map (nine semiannual rounds, June 2010 to June 2014, block-level files aggregated with Census block populations and NTIA's county "Analyze" tables) spliced to the FCC Form 477 fixed-deployment files and county Area Tables (fourteen rounds, December 2014 to June 2021). The second is the instrument used by <a href="https://www.nber.org/papers/w35310">Myers and Hooper (2026)</a>: the share of county population living in 2000 Census blocks with any AT&amp;T Mobility mobile-wireless coverage in the December 2010 release, a snapshot of the network that carried the iPhone during AT&amp;T's June 2007 to February 2011 exclusivity. Myers and Hooper use this same public release (not a proprietary carrier map), code a block as covered if any AT&amp;T polygon touches it, and classify counties with more than 90% of population covered as treated and under 10% as control; our reconstruction yields {n_tr:,} treated, {n_co:,} control and {n_int:,} intermediate counties against their 822, 1,490 and 795, with a mean county share of {pct(att_mean)}. AT&amp;T's 2010 footprint is metropolitan ({pct(att_metro)} of population covered in metro counties versus {pct(att_non)} elsewhere) and only loosely related to the 4G timing used in Part 2 (correlation with the LTE onset year {r_lte:+.2f}; counties whose metro had LTE by the 2012 school year averaged {pct(att_lte)} coverage versus {pct(att_late)} for later or undated metros) or to Verizon's footprint (r = {r_vz:+.2f}). Methods, sources and carrier roll-ups are in <code>notes/broadband.md</code>; the compiled tables are <code>data/compiled/broadband/county_broadband_panel.csv</code> and <code>county_att_mobile_2010.csv</code>.</p>
<p>Across all counties, wireline availability was already high in December 2010 ({pct(ps.loc['2010-12', 'wireline_any'])} of population on average) and barely moved to 2021 ({pct(ps.loc['2021-06', 'wireline_any'])}); the variation is in speed. Wireline service at 25 Mbps or faster reached {pct(ps.loc['2010-12', 'wireline_ge25'])} of county population in December 2010, {pct(ps.loc['2013-12', 'wireline_ge25'])} in December 2013, {pct(ps.loc['2016-12', 'wireline_ge25'])} in December 2016 and {pct(ps.loc['2021-06', 'wireline_ge25'])} in June 2021, mostly cable DOCSIS 3 upgrades that reached rural counties last. Mobile wireless covered {pct(ps.loc['2010-12', 'mobile_any'])} of county population in December 2010 and {pct(ps.loc['2014-06', 'mobile_any'])} by June 2014, when the NTIA series ends; the FCC's later mobile data are provider shapefiles without a county summary and were not used.</p>
<h4>Continuous dose, 2010-2021</h4>
<p>The design is Phase 1's: county-by-grade series with county-by-grade and state-by-year fixed effects, standard errors clustered by 2013 CBSA, each coverage measure interpolated to the survey spring. The coefficients are per 10 percentage points of county population gaining access.</p>
{ctx.fig_div('bb_coefficients')}
<p class="caption">Left: effect of +10 pp of county population covered on the share of students sad or hopeless (CA, IL, ME, PA, WA) and considering suicide (CA, IL, ME, MN, PA, WA), 2010-2021, county x grade and state x year fixed effects, 95% intervals clustered by CBSA. Right: Minnesota 1998-2019, coefficient on the county's AT&amp;T December-2010 coverage share interacted with each survey wave (2007, the last pre-iPhone wave, is the reference), county x grade and year fixed effects; a value of -1 means that a fully covered county moved 1 pp lower than an uncovered county relative to 2007.</p>
{t_dose}
<p class="caption">Coefficient (SE) per +10 pp of county population covered, county x grade series 2010-2021 (the mobile measure ends in 2014). Bold: |t| &gt; 1.96. The last column repeats the all-sex ideation estimate on 2010-2019 surveys, before the pandemic waves.</p>
<p>Any-wireline availability, which varies little, is unrelated to sadness ({f(g(dose, measure='wireline_any', item='sad_hopeless', sex='all', sample='2010-2021').coef_per10pp, g(dose, measure='wireline_any', item='sad_hopeless', sex='all', sample='2010-2021').se_per10pp)} pp per 10 pp) and weakly positive for suicidal ideation ({f(rany.coef_per10pp, rany.se_per10pp)}). The speed tiers that did spread during the decade are positively associated with ideation: {f(r10.coef_per10pp, r10.se_per10pp)} pp per 10 pp of population gaining 10 Mbps wireline and {f(r25.coef_per10pp, r25.se_per10pp)} for 25 Mbps, with n = {int(r25.n):,} county-grade-years in {int(r25.counties)} counties; restricted to 2010-2019 the 25 Mbps estimate is {f(r25_19.coef_per10pp, r25_19.se_per10pp)} and the 10 Mbps estimate {f(r10_19.coef_per10pp, r10_19.se_per10pp)}. Sadness shows nothing comparable ({f(s25.coef_per10pp, s25.se_per10pp)} for 25 Mbps). Where sex splits exist (California and Maine), the ideation gradient is similar for girls ({f(r25f.coef_per10pp, r25f.se_per10pp)}) and boys ({f(r25m.coef_per10pp, r25m.se_per10pp)}), and girls' sadness is if anything negative ({f(s25f.coef_per10pp, s25f.se_per10pp)}). Mobile coverage over 2010-2014, the measure closest to smartphone access, points the other way: {f(mob.coef_per10pp, mob.se_per10pp)} for ideation and {f(mobs.coef_per10pp, mobs.se_per10pp)} for sadness, in the counties (mostly rural) that were still gaining 3G/4G coverage.</p>
<p>Two scalings put the ideation gradient in context. Within-county variation in 25 Mbps wireline coverage over the period has a standard deviation of {r25.dose_sd_within:.0f} pp, so one within-county standard deviation corresponds to {r25.pct_per_within_sd:+.1f}% of the mean ideation rate ({r25.mean_outcome:.1f}%); <a href="https://www.nber.org/papers/w34614">Churchill and Johnson</a> report 9.3-16.5% per state-level standard deviation of access. The Phase 1 metro LTE contrast on the same panels gave {f(lte_con.did, lte_con.se)} pp for ideation and {f(lte_sad.did, lte_sad.se)} for sadness, and the NTIA smartphone-adoption dose {f(ntia[(ntia.item == 'considered_suicide') & (ntia.sex == 'all')].coef_per10pp.iloc[0], ntia[(ntia.item == 'considered_suicide') & (ntia.sex == 'all')].se.iloc[0])} per 10 pp. The wireline-speed gradient is therefore the first positive county-level connectivity association in these panels, but it is a gradient in cable upgrades that arrived late in rural counties whose ideation rates also rose late, with state-by-year effects removing only the state-wide part of that timing; it is not a smartphone measure, and the mobile measure that is one has the opposite sign.</p>
<h4>The AT&amp;T 2010 footprint and Minnesota's 1998-2019 county series</h4>
<p>Minnesota's biennial-to-triennial county tables (1998, 2001, 2004, 2007, 2010, 2013, 2016, 2019; 87 counties) are the only county series that bracket the iPhone-exclusivity window. If early smartphone access raised distress, counties with AT&amp;T coverage should have pulled above uncovered counties after 2007. They did not. Relative to 2007, fully covered counties were {f(e10.coef, e10.se)} pp lower in 2010, {f(e13.coef, e13.se)} in 2013 and {f(e19.coef, e19.se)} in 2019 on grade-9 suicidal ideation, with pre-period coefficients of {f(e98.coef, e98.se)} (1998) and {f(e04.coef, e04.se)} (2004). Pooled, AT&amp;T coverage x post-2007 is {f(cs.loc[P, 'coef'], cs.loc[P, 'se'])} pp for ideation (mean {cs.loc[P, 'mean_pre2007']:.1f}% before 2007), {f(at.loc[P, 'coef'], at.loc[P, 'se'])} for attempts, and {f(sd30.loc[P, 'coef'], sd30.loc[P, 'se'])} for the 30-day sadness item that ends in 2010; the Myers-Hooper binary contrast gives {f(cs.loc[B, 'coef'], cs.loc[B, 'se'])} for ideation. Pre-trends are flat ({f(cs.loc[PRE, 'coef'], cs.loc[PRE, 'se'])} pp per wave for ideation). Verizon's footprint, whose customers could not buy an iPhone until February 2011, shows no comparable pattern ({f(cs.loc[VZ, 'coef'], cs.loc[VZ, 'se'])}).</p>
{t_mn}
<p class="caption">Minnesota Student Survey county series, county x grade and year fixed effects, standard errors clustered by CBSA (county outside CBSAs). AT&amp;T share is the share of county population in blocks with AT&amp;T mobile coverage, December 2010 (0-1), so a coefficient is the difference between a fully covered and an uncovered county. The 30-day items were last asked in 2010. "Treated vs control" follows Myers and Hooper (&gt;90% vs &lt;10%, intermediate counties dropped).</p>
{ctx.fig_div('bb_scatter')}
<p class="caption">Left: Minnesota counties, change in grade-9 suicidal ideation between the 2007 and 2019 waves against the AT&amp;T December-2010 coverage share (blue: metropolitan counties; dotted line: population-weighted fit, slope {f(ld19.coef, ld19.se)} pp per unit share; {f(ld19c.coef, ld19c.se)} with metro and log-population controls; the 2001-2007 placebo change gives {f(ldp.coef, ldp.se)}). Right: {'states, change in the average annual youth (10-19) suicide rate between 2003-07 and 2013-17 against the state population-weighted AT&amp;T share (CDC WONDER, no suppression at state level).' if has_state else 'counties with unsuppressed youth suicide counts.'}</p>
<p>Extending the same test to the five states whose county series begin after 2007 can only ask whether high-AT&amp;T counties kept diverging during 2010-2019. Pooled across all six states with county-by-grade and state-by-year effects, the differential trend is {f(pool.coef, pool.se)} pp per decade for ideation ({int(pool.counties)} counties) and {f(pools.coef, pools.se)} for sadness; by sex in California and Maine, {f(poolf.coef, poolf.se)} for girls and {f(poolm.coef, poolm.se)} for boys. Maine's 16 counties show no cross-sectional gradient in 2009 and none in the 2009-2019 change (correlations between -0.2 and +0.1).</p>
<h4>County and state youth suicide</h4>
<p>CDC WONDER's web form (the API refuses sub-national queries) supplied suicide deaths and population for ages 10-19 by county for 1999-2002, 2003-07, 2008-12, 2013-17 and 2018-22, with counts under 10 suppressed. Suppression binds hard at this age: only about {pct(uns.share_us_pop)} of youth live in counties with reportable counts in both 2003-07 and 2013-17, and the reportable set mixes large counties with small counties that happened to record zero deaths. The AT&amp;T estimate changes sign with the treatment of suppressed cells ({f(uns.coef, uns.se)} deaths per 100,000 per year, for a fully covered versus uncovered county, on reportable counties; {f(imp.coef, imp.se)} when suppressed counts are set to the midpoint 5), and the {int(big.counties)} large counties where suppression is rare have almost no AT&amp;T variation (mean share {pct(big.att_mean)}, SD {big.att_sd:.2f}). The county suicide test is therefore not informative with public data; the state series, which has no suppression, is the usable fallback.</p>
{t_su}
<p class="caption">County rows: change in the average annual suicide rate per 100,000 youths aged 10-19 between 2003-07 and 2013-17, regressed on the AT&amp;T December-2010 coverage share with state fixed effects and youth-population weights. State rows: state x year panel 1999-2024 (CDC WONDER, no suppression for all youth and boys), rate on the state's population-weighted AT&amp;T share x post-2007 with state and year fixed effects, youth-population weights and standard errors clustered by state; the last column adds the state's non-metro population share x post-2007. Bold: |t| &gt; 1.96.</p>
{'<p>' + ('At state level, youth suicide rose by ' + f(g(st, sex='all', spec='state AT&T share (0-1) x post-2007, 1999-2023, state + year FE, youth-population weights').coef, g(st, sex='all', spec='state AT&T share (0-1) x post-2007, 1999-2023, state + year FE, youth-population weights').se) + ' deaths per 100,000 per year more after 2007 in a fully AT&T-covered state than in an uncovered one (mean pre-2007 rate ' + f"{g(st, sex='all', spec='state AT&T share (0-1) x post-2007, 1999-2023, state + year FE, youth-population weights').mean_rate_pre:.1f}" + '); the 1999-2007 pre-trend is ' + f(g(st, sex='all', spec='pre-trend 1999-2007: att_state x years/10').coef, g(st, sex='all', spec='pre-trend 1999-2007: att_state x years/10').se) + ' per decade and the 1999-2002 to 2003-07 placebo change ' + f(g(st, sex='all', spec='placebo: rate 2003-07 minus 1999-2002 on att_state').coef, g(st, sex='all', spec='placebo: rate 2003-07 minus 1999-2002 on att_state').se) + '. Girls: ' + f(g(st, sex='F', spec='state AT&T share (0-1) x post-2007, 1999-2023, state + year FE, youth-population weights').coef, g(st, sex='F', spec='state AT&T share (0-1) x post-2007, 1999-2023, state + year FE, youth-population weights').se) + '; boys: ' + f(g(st, sex='M', spec='state AT&T share (0-1) x post-2007, 1999-2023, state + year FE, youth-population weights').coef, g(st, sex='M', spec='state AT&T share (0-1) x post-2007, 1999-2023, state + year FE, youth-population weights').se) + '. With the state non-metro population share x post-2007 added, the AT&T coefficient is ' + f(g(st, sex='all', spec="same, controlling the state's non-metro population share x post-2007").coef, g(st, sex='all', spec="same, controlling the state's non-metro population share x post-2007").se) + ' and the non-metro term ' + f(g(st, sex='all', spec='non-metro share x post-2007 in that model').coef, g(st, sex='all', spec='non-metro share x post-2007 in that model').se) + ': the 2010s rise in youth suicide was a rural rise, and the AT&T 2010 footprint is first of all an urbanicity map. Fifty-one states give little power, and state-year counts for girls are mostly suppressed, so this is a weak test.') + '</p>' if has_state else ''}
<h4>What the broadband literature identifies</h4>
{lit}
<div class="note"><strong>Assessment.</strong> Replacing LTE launch dates with continuous coverage and the AT&amp;T 2010 footprint sharpens the county test without changing its answer on H1's rollout channel. The one positive association, between wireline speed upgrades and suicidal ideation ({f(r25.coef_per10pp, r25.se_per10pp)} pp per 10 pp at 25 Mbps), is small relative to Churchill and Johnson's state estimates, absent for sadness and for the mobile measure, and tracks cable upgrades that reached rural counties last; it is consistent with the home-broadband studies from Europe but does not isolate smartphones. The AT&amp;T 2007-11 instrument, which Myers and Hooper show predicted early iPhone adoption and lower teen births, predicts no rise in Minnesota adolescents' suicidal ideation, attempts or 30-day sadness after 2007 (coefficients between {min(cs.loc[P, 'coef'], at.loc[P, 'coef'], sd30.loc[P, 'coef']):+.1f} and {max(cs.loc[P, 'coef'], at.loc[P, 'coef'], sd30.loc[P, 'coef']):+.1f} pp for full coverage, standard errors 0.4-0.8) and no differential 2010-19 trend across six states; county youth suicide cannot be tested with public suppressed counts, and the state series is a weak test. For H1 this means that the geographic separation in early smartphone access that Myers and Hooper exploit left no visible mark on the one U.S. county mental-health series that spans it, which fits Part 2's conclusion that the 2010s rise was close to simultaneous across places; H2, H3 and H0 are not addressed here. A stronger design needs an outcome measured across the 2007-11 window in many states (restricted-use YRBS state files with county codes, or NSDUH substate estimates) rather than Minnesota alone.</div>"""
    return {"broadband": html}
